// Evolution speaks Baileys. The app speaks its own contract. This is the only
// node that knows both, on purpose: when Evolution changes shape, one node
// changes.
//
// Every item, not just the first. A webhook usually delivers one message, but
// Evolution can batch, and `$input.first()` would drop the rest silently.
return $input.all().flatMap((item) => {
  const input = item.json;
  const body = input.body ?? input;
  const data = body.data ?? {};
  const key = data.key ?? {};

  // Our own outgoing messages come back through the same event.
  if (key.fromMe) return [];

  const m = data.message ?? {};
  const text = m.conversation ?? m.extendedTextMessage?.text ?? '';
  const caption = m.imageMessage?.caption ?? m.videoMessage?.caption
    ?? m.documentMessage?.caption ?? '';

  let type = 'text';
  if (m.imageMessage) type = 'image';
  else if (m.audioMessage) type = 'audio';
  else if (m.videoMessage) type = 'video';
  else if (m.documentMessage) type = 'document';

  // Nothing to read and nothing to look at. Not an error, just not a change.
  if (!text && !caption && type === 'text') return [];

  const jid = String(key.remoteJid ?? '');
  // Groups end @g.us and carry the real sender in `participant`. A group
  // message signed by the group would resolve to no user at all.
  const sender = jid.endsWith('@g.us') ? String(key.participant ?? '') : jid;
  const phoneDigits = sender.split('@')[0].split(':')[0];
  if (!phoneDigits) return [];

  const payload = {
    idempotency_key: 'evolution:' + (key.id ?? ''),
    received_at: new Date((Number(data.messageTimestamp) || Date.now() / 1000) * 1000).toISOString(),
    sender: {
      phone: '+' + phoneDigits,
      display_name: data.pushName || undefined,
    },
    message: {
      type,
      text: text || undefined,
      caption: caption || undefined,
      media: [],
    },
  };

  return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];
});

// The Gmail Trigger with `simple: false` returns a PARSED message, and `from`,
// `to` and `cc` are mailparser ADDRESS OBJECTS:
//
//   { value: [{ address: 'a@b.com', name: 'A B' }], text: '...', html: '...' }
//
// The first version of this node treated them as strings. `String(m.from)`
// yields the literal text "[object Object]", which the app correctly refused
// with `400 from: Invalid email`. It failed loudly, which is the only good
// thing about it.
const addressesOf = (field) => {
  if (!field) return [];
  const value = Array.isArray(field) ? field : field.value;
  if (Array.isArray(value)) {
    return value
      .map((entry) => String(entry?.address ?? '').trim().toLowerCase())
      .filter(Boolean);
  }
  // A plain string, kept because a future Gmail node version may return one:
  // "Name <a@b.com>, c@d.com".
  return String(field.text ?? field)
    .split(',')
    .map((part) => {
      const match = part.match(/<([^>]+)>/);
      return (match ? match[1] : part).trim().toLowerCase();
    })
    .filter(Boolean);
};

const nameOf = (field) => {
  const value = field && !Array.isArray(field) ? field.value : field;
  if (Array.isArray(value) && value[0]?.name) return String(value[0].name).trim();
  return '';
};

// The app refuses a captured message over 32 MB, because attachments are held
// base64 encoded in the event row until somebody says which project it is. So
// the budget is spent here, where a skipped file can still be NAMED in the
// body, rather than at the door where the whole email would bounce.
const BASE64_BUDGET = 20 * 1024 * 1024;

// EVERY item, not just the first. The trigger delivers a BATCH when more than
// one message arrived since the last poll, and `$input.first()` dropped all but
// one of them — an email that vanishes with no error anywhere. Two arrived on
// the first real test and only one was ever sent.
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const m = items[i].json;
  const address = addressesOf(m.from)[0] ?? '';

  // No readable sender means the app cannot attribute it to anybody. Better to
  // drop it here, visibly, than to POST a body we know will be refused.
  if (!address) continue;

  // ── Attachments become evidence ───────────────────────────────────────
  // The trigger writes each one to a binary property: attachment_0, _1, ...
  // The bytes are read through the helper and NOT off `binary[key].data`,
  // because when n8n is configured to keep binary on the filesystem or S3
  // that field is absent — and the naive read produces an empty file with no
  // error, which is the worst way to lose a site photograph.
  const attachments = [];
  const skipped = [];
  const binary = items[i].binary ?? {};
  let budget = BASE64_BUDGET;

  for (const key of Object.keys(binary)) {
    const meta = binary[key] ?? {};
    const fileName = meta.fileName || key;
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(i, key);
      const encoded = buffer.toString('base64');
      if (encoded.length > budget) {
        skipped.push(fileName + ' (too large to forward)');
        continue;
      }
      budget -= encoded.length;
      attachments.push({
        external_id: String(m.id ?? 'gmail') + ':' + key,
        file_name: fileName,
        mime_type: meta.mimeType || 'application/octet-stream',
        content_base64: encoded,
      });
    } catch (error) {
      // One unreadable attachment must never lose the email it came with.
      skipped.push(fileName + ' (could not be read)');
    }
  }

  let bodyText = m.text ?? m.textAsHtml ?? '';
  if (skipped.length > 0) {
    bodyText += '\n\n[Not attached to this record: ' + skipped.join(', ') + ']';
  }

  const payload = {
    idempotency_key: 'gmail:' + (m.id ?? m.messageId ?? ''),
    received_at: new Date(m.date ?? Date.now()).toISOString(),
    from: { address, name: nameOf(m.from) || undefined },
    to: addressesOf(m.to),
    cc: addressesOf(m.cc),
    subject: m.subject ?? '',
    body_text: bodyText,
    attachments,
  };

  out.push({ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } });
}

return out;

// The project code comes from the folder name, which is where the app puts it
// (`DXB-001 — Dubai Office Fit-Out`). If it cannot be read, send it anyway and
// let the app reject it: a 4xx that names the file beats a document filed
// against a project somebody guessed at.
//
// Every item, not just the first. One Drive poll routinely returns several new
// files, and `$input.first()` filed one and lost the rest with no error.
return $input.all().map((item) => {
  const f = item.json;
  const name = f.name ?? '';
  const parentName = f.parentFolderName ?? f.parents?.[0]?.name ?? '';
  const code = (parentName.match(/^[A-Z]{2,4}-\d{3}/) ?? name.match(/^[A-Z]{2,4}-\d{3}/) ?? [''])[0];

  const payload = {
    idempotency_key: 'drive:' + (f.id ?? ''),
    project_code: code,
    document_name: name,
    document_type: 'other',
    external_file_id: f.id,
    source_url: f.webViewLink || undefined,
  };

  return { json: { ts: String(Date.now()), payload: JSON.stringify(payload) } };
});

// The app treats its own outbound request as 'queued', never 'sent'. This
// call is the only thing that can move a notification to delivered, and the
// only evidence that a message actually left the building.
const src = $('D3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'sent',
  external_message_id: $input.first().json.id ?? undefined,
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// A failed send is recorded as failed, with the reason. Silence here would
// leave a notification pending for ever and nobody would know it never went.
const src = $('D3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'failed',
  failure_reason: String($input.first().json.error?.message ?? 'Gmail send failed').slice(0, 400),
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

// The app treats its own outbound request as 'queued', never 'sent'. This
// call is the only thing that can move a notification to delivered, and the
// only evidence that a message actually left the building.
const src = $('E3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'sent',
  external_message_id: $input.first().json.key?.id ?? undefined,
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

const src = $('E3 · Signature Valid?').first().json.body;
const payload = {
  idempotency_key: 'delivery:' + src.notification_id,
  notification_id: src.notification_id,
  status: 'failed',
  failure_reason: String($input.first().json.error?.message ?? 'Evolution send failed').slice(0, 400),
};
return [{ json: { ts: String(Date.now()), payload: JSON.stringify(payload) } }];

const e = $input.first().json;
const node = e.execution?.lastNodeExecuted ?? '';
const lane = (node.match(/^([A-Z])\d/) ?? [])[1] ?? '?';

const LANES = {
  A: 'WhatsApp capture', B: 'Email capture', C: 'Document watch',
  D: 'Email out', E: 'WhatsApp out', S: 'Scheduled jobs',
  F: 'Client follow-up', G: 'Weekly report',
};

return [{ json: {
  lane,
  lane_name: LANES[lane] ?? 'Unknown lane',
  node,
  message: e.execution?.error?.message ?? 'No message',
  workflow: e.workflow?.name ?? '',
  execution_url: e.execution?.url ?? '',
  at: new Date().toISOString(),
} }];
